<?php require_once '../functions.php';need_admin();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['delete'])){$pdo->prepare('DELETE FROM rules WHERE id=?')->execute([(int)$_POST['id']]);$msg='Aturan dihapus.';}else{$id=(int)($_POST['id']??0);$v=[(int)$_POST['disease_id'],(int)$_POST['symptom_id'],(float)$_POST['cf_expert'],trim($_POST['note'])];if($v[2]<0||$v[2]>1)$msg='Nilai CF pakar harus antara 0 dan 1.';else{if($id)$pdo->prepare('UPDATE rules SET disease_id=?,symptom_id=?,cf_expert=?,note=? WHERE id=?')->execute([...$v,$id]);else{$sql=$dbDriver==='pgsql'?'INSERT INTO rules(disease_id,symptom_id,cf_expert,note) VALUES(?,?,?,?) ON CONFLICT (disease_id,symptom_id) DO UPDATE SET cf_expert=EXCLUDED.cf_expert,note=EXCLUDED.note':'INSERT INTO rules(disease_id,symptom_id,cf_expert,note) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE cf_expert=VALUES(cf_expert),note=VALUES(note)';$pdo->prepare($sql)->execute($v);}$msg='Aturan tersimpan.';}}}$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM rules WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$diseases=$pdo->query('SELECT id,code,name FROM diseases ORDER BY code')->fetchAll();$symptoms=$pdo->query('SELECT id,code,name,category FROM symptoms ORDER BY code')->fetchAll();$rows=$pdo->query('SELECT r.*,d.name disease,s.name symptom,s.code symptom_code,s.category FROM rules r JOIN diseases d ON d.id=r.disease_id JOIN symptoms s ON s.id=r.symptom_id ORDER BY d.code,s.code')->fetchAll();header_html('Kelola aturan');include '_nav.php';?><section class="page-head"><span class="eyebrow">MESIN INFERENSI</span><h1>Aturan & nilai CF pakar</h1><p>Bobot CF Pakar dari 0 sampai 1 menunjukkan kekuatan hubungan gejala terhadap penyakit.</p></section><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><section class="card admin-form"><h2><?=$edit?'Ubah aturan':'Tambah aturan'?></h2><form method="post" class="form form-grid"><input type="hidden" name="id" value="<?=$edit['id']??''?>"><label>Penyakit<select name="disease_id" required><?php foreach($diseases as $d):?><option value="<?=$d['id']?>" <?=($edit['disease_id']??'')==$d['id']?'selected':''?>><?=e($d['code'].' · '.$d['name'])?></option><?php endforeach;?></select></label><label>Gejala<select name="symptom_id" required><?php foreach($symptoms as $s):?><option value="<?=$s['id']?>" <?=($edit['symptom_id']??'')==$s['id']?'selected':''?>><?=e($s['code'].' · '.$s['name'].' ('.$s['category'].')')?></option><?php endforeach;?></select></label><label>CF pakar (0–1)<input name="cf_expert" type="number" min="0" max="1" step="0.01" value="<?=e($edit['cf_expert']??'0.8')?>" required></label><label>Catatan sumber<input name="note" value="<?=e($edit['note']??'')?>" placeholder="Contoh: Embrapa 2024"></label><button class="button">Simpan aturan</button></form></section><div class="table-wrap card"><table><thead><tr><th>Penyakit</th><th>Gejala</th><th>Kategori</th><th>CF pakar</th><th>Sumber</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['disease'])?></td><td><?=e($r['symptom_code'].' · '.$r['symptom'])?></td><td><?=$r['category']??''?></td><td><?=number_format($r['cf_expert'],2)?></td><td><?=e($r['note'])?></td><td><a href="?edit=<?=$r['id']?>">Ubah</a> <form class="inline-form" method="post" onsubmit="return confirm('Hapus aturan ini?')"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="delete" value="1" class="link-danger">Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div><?php footer_html();?>
